  ```js
  'use strict';
  // Nightly. Writes exports/rating-summary.json: for each agent, how many ratings their tickets received in
  // the past seven days and the average score. A rating 7 days old or older is not counted.
  const fs = require('node:fs');
  const path = require('node:path');
  const { EXPORT_DIR } = require('./export-tickets');

  const WINDOW_DAYS = 7;
  const DAY = 24 * 60 * 60 * 1000;

  function ratingSummary(store, { now = new Date(), dir = EXPORT_DIR } = {}) {
    const byAgent = new Map();
    for (const r of store.listRatings()) {
      if (!r.agentId) continue;
      if (now.getTime() - new Date(r.ratedAt).getTime() >= WINDOW_DAYS * DAY) continue;
      const bucket = byAgent.get(r.agentId) || [];
      bucket.push(r.score);
      byAgent.set(r.agentId, bucket);
    }
    const rows = [...byAgent.entries()].map(([agentId, scores]) => ({
      agentId,
      count: scores.length,
      average: Math.round((scores.reduce((a, b) => a + b, 0) / scores.length) * 100) / 100,
    }));
    fs.mkdirSync(dir, { recursive: true });
    const file = path.join(dir, 'rating-summary.json');
    fs.writeFileSync(file, JSON.stringify(rows, null, 2) + '\n');
    return { file, rows };
  }

  module.exports = { ratingSummary, WINDOW_DAYS };
  ```

